import kotlinx.serialization.Serializable

@Serializable
data class ProfileResponse(
    val userId: String,          // Non-nullable: Đảm bảo luôn có giá trị hợp lệ
    val nickname: String? = null // Nullable: Cho phép vắng mặt trong payload JSON
)

fun resolveDisplayName(profile: ProfileResponse?): String {
    // Kết hợp Safe-call (?.) và Elvis operator (?:) với early return pattern
    val user = profile ?: return "Khách vãng lai"

    // Smart-cast tự động khi kiểm tra null
    return if (user.nickname != null) {
        user.nickname.trim() // Compiler hiểu nickname là non-null tại đây
    } else {
        "User #${user.userId.take(6)}"
    }
}

