class NavigationHelper(private val context: Context) {
    // 1. Explicit Intent: Điều hướng an toàn trong nội bộ ứng dụng
    fun openSettingsScreen() {
        val explicitIntent = Intent(context, SettingsActivity::class.java).apply {
            putExtra("EXTRA_SETTINGS_TAB", "SECURITY")
        }
        context.startActivity(explicitIntent)
    }

    // 2. Implicit Intent: Mở trình duyệt web hệ thống
    fun openWebPage(url: String) {
        val implicitIntent = Intent(Intent.ACTION_VIEW, Uri.parse(url)).apply {
            addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
        }
        // Đảm bảo không crash nếu thiết bị không có trình duyệt xử lý
        if (implicitIntent.resolveActivity(context.packageManager) != null) {
            context.startActivity(implicitIntent)
        }
    }
}

