class ComputationViewModel : ViewModel() {

    fun executeHeavyCalculation() {
        // Bắt đầu trên Main Thread (UI)
        viewModelScope.launch {
            // Chuyển sang Worker Thread (Dispatchers.Default)
            // để không block Main Thread và ngăn ngừa ANR
            val result = withContext(Dispatchers.Default) {
                performCpuIntensiveWork()
            }
            // Tự động quay lại Main Thread để cập nhật UI
            updateUiWithResult(result)
        }
    }

    private fun performCpuIntensiveWork(): Long {
        var sum = 0L
        for (i in 1..10_000_000) { sum += i }
        return sum
    }

    private fun updateUiWithResult(result: Long) { /* UI update */ }
}

