}

import android.content.Context
import android.content.Intent

fun setupUserIntent(context: Context, token: String?): Intent? {
    // let: Xử lý an toàn khi token khác null và trả về Intent
    return token?.let { nonNullToken ->
        // apply: Khởi tạo và gán nhiều thuộc tính lên Intent instance
        Intent().apply {
            action = Intent.ACTION_SEND
            putExtra("AUTH_TOKEN", nonNullToken)
            type = "text/plain"
        }
    }?.also { finalIntent ->
        // also: Thực hiện side-effect ghi log bổ sung mà không đổi intent trả về
        println("Đã cấu hình intent với action: ${finalIntent.action}")
    }
}

