fun shareImageFile(context: Context, imageFile: File) {
    // Biến file private thành Content URI thông qua FileProvider
    val contentUri: Uri = FileProvider.getUriForFile(
        context,
        "${context.packageName}.fileprovider",
        imageFile
    )

    val shareIntent = Intent(Intent.ACTION_SEND).apply {
        type = "image/png"
        putExtra(Intent.EXTRA_STREAM, contentUri)
        // Cấp quyền đọc tạm thời cho ứng dụng tiếp nhận
        addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
    }
    context.startActivity(Intent.createChooser(shareIntent, "Chia sẻ ảnh"))
}

