class AuthHeaderInterceptor(private val tokenProvider: () -> String) : Interceptor {
    override fun intercept(chain: Interceptor.Chain): Response {
        val originalRequest = chain.request()

        // Tạo bản sao request mới và gắn thêm Header
        val authenticatedRequest = originalRequest.newBuilder()
            .header("Authorization", "Bearer ${tokenProvider()}")
            .header("X-App-Platform", "Android")
            .method(originalRequest.method, originalRequest.body)
            .build()

        // Chuyển tiếp request trong chuỗi xử lý và nhận response
        return chain.proceed(authenticatedRequest)
    }
}

fun buildHttpClient(interceptor: AuthHeaderInterceptor): OkHttpClient {
    return OkHttpClient.Builder()
        .addInterceptor(interceptor) // Đăng ký Application Interceptor
        .build()
}

import okhttp3.Authenticator
import okhttp3.Request
import okhttp3.Response
import okhttp3.Route

class TokenAuthenticator(
    private val tokenStorage: TokenStorage,
    private val authService: AuthRefreshService
) : Authenticator {

    override fun authenticate(route: Route?, response: Response): Request? {
        // Ngăn chặn vòng lặp vô tận nếu thử lại vẫn bị 401
        if (responseCount(response) >= 3) return null

        synchronized(this) {
            val currentToken = tokenStorage.getAccessToken()
            val requestToken = response.request.header("Authorization")?.removePrefix("Bearer ")

            // Nếu token đã được thread khác refresh, dùng ngay token mới để retry
            val freshToken = if (currentToken != requestToken && currentToken != null) {
                currentToken
            } else {
                // Thực hiện refresh token đồng bộ
                val newTokens = authService.blockingRefreshToken(tokenStorage.getRefreshToken())
                    ?: run {
                        tokenStorage.clearTokens() // Buộc logout nếu refresh token hỏng
                        return null
                    }
                tokenStorage.saveTokens(newTokens.access, newTokens.refresh)
                newTokens.access
            }

            return response.request.newBuilder()
                .header("Authorization", "Bearer $freshToken")
                .build()
        }
    }

    private fun responseCount(response: Response): Int {
        var count = 1
        var prior = response.priorResponse
        while (prior != null) { count++; prior = prior.priorResponse }
        return count
    }
}
interface TokenStorage { fun getAccessToken(): String?; fun getRefreshToken(): String?; fun saveTokens(a: String, r: String); fun clearTokens() }
interface AuthRefreshService { fun blockingRefreshToken(r: String?): NewTokens? }
class NewTokens(val access: String, val refresh: String)

