class LogSyncWorker(context: Context, params: WorkerParameters) : CoroutineWorker(context, params) {
    override suspend fun doWork(): Result {
        return try {
            // Thực hiện tác vụ gửi dữ liệu ngầm lên server
            uploadLogsToServer()
            Result.success()
        } catch (e: Exception) {
            if (runAttemptCount < 3) Result.retry() else Result.failure()
        }
    }
    private fun uploadLogsToServer() {}
}

fun schedulePeriodicLogSync(context: Context) {
    val constraints = Constraints.Builder()
        .setRequiredNetworkType(NetworkType.UNMETERED) // Bắt buộc mạng Wifi không tốn phí
        .setRequiresCharging(true)                     // Đang cắm sạc
        .build()

    val syncRequest = PeriodicWorkRequestBuilder<LogSyncWorker>(24, TimeUnit.HOURS)
        .setConstraints(constraints)
        .setBackoffCriteria(BackoffPolicy.EXPONENTIAL, 10, TimeUnit.MINUTES)
        .build()

    WorkManager.getInstance(context).enqueueUniquePeriodicWork(
        "UniqueDailyLogSync",
        ExistingPeriodicWorkPolicy.KEEP,
        syncRequest
    )
}

import androidx.paging.PagingSource
import androidx.paging.PagingState

class ProductPagingSource(private val apiService: ProductApiService) : PagingSource<Int, ProductItem>() {
    override suspend fun load(params: LoadParams<Int>): LoadResult<Int, ProductItem> {
        val pageNumber = params.key ?: 1
        return try {
            val response = apiService.fetchProducts(page = pageNumber, pageSize = params.loadSize)
            LoadResult.Page(
                data = response.items,
                prevKey = if (pageNumber == 1) null else pageNumber - 1,
                nextKey = if (response.items.isEmpty()) null else pageNumber + 1
            )
        } catch (e: Exception) {
            LoadResult.Error(e)
        }
    }

    override fun getRefreshKey(state: PagingState<Int, ProductItem>): Int? {
        return state.anchorPosition?.let { anchor ->
            state.closestPageToPosition(anchor)?.prevKey?.plus(1)
                ?: state.closestPageToPosition(anchor)?.nextKey?.minus(1)
        }
    }
}
