class TransferMoneyUseCase(
    private val accountRepo: AccountRepository,
    private val transactionRepo: TransactionRepository
) {
    // Sử dụng operator fun invoke để gọi Use Case trực quan
    suspend operator fun invoke(senderId: String, receiverId: String, amount: Long): Result<String> {
        val senderAccount = accountRepo.getAccount(senderId)
        if (senderAccount.balance < amount) {
            return Result.failure(IllegalStateException("Số dư tài khoản không đủ để thực hiện giao dịch"))
        }

        val transactionId = transactionRepo.createTransfer(senderId, receiverId, amount)
        accountRepo.refreshLocalBalance(senderId)
        return Result.success(transactionId)
    }
}
