fun downloadDynamicKycModule(context: Context, onInstalled: () -> Unit) {
    val splitInstallManager = SplitInstallManagerFactory.create(context)
    val moduleName = "kyc_verification_feature"

    if (splitInstallManager.installedModules.contains(moduleName)) {
        onInstalled()
        return
    }

    val request = SplitInstallRequest.newBuilder()
        .addModule(moduleName)
        .build()

    splitInstallManager.registerListener { state ->
        if (state.sessionId() == state.sessionId()) {
            when (state.status()) {
                SplitInstallSessionStatus.INSTALLED -> onInstalled()
                SplitInstallSessionStatus.FAILED -> println("Tải module thất bại")
            }
        }
    }
    splitInstallManager.startInstall(request)
}

import android.app.Activity
import androidx.metrics.performance.JankStats
import androidx.metrics.performance.PerformanceMetricsState

fun setupJankMonitoring(activity: Activity) {
    // Sử dụng JankStats để theo dõi giật lag khung hình theo thời gian thực
    val jankListener = JankStats.OnFrameListener { frameData ->
        if (frameData.isJank) {
            // Ghi nhận khung hình render vượt quá 16ms
            println("Phát hiện giật lag: Frame duration = ${frameData.frameDurationUiNanos / 1_000_000} ms")
        }
    }

    val jankStats = JankStats.createAndTrack(activity.window, jankListener)
    // Gắn thêm ngữ cảnh UI (ví dụ đang ở màn hình nào)
    val metricsState = PerformanceMetricsState.getHolderForHierarchy(activity.window.decorView).state
    metricsState?.putState("CurrentScreen", "ProductDetailScreen")
}

