import android.graphics.Bitmap
import android.util.LruCache

object MemoryAwareBitmapCache {
    // Cấp phát 1/8 dung lượng heap tối đa cho bộ nhớ đệm ảnh
    private val maxMemory = (Runtime.getRuntime().maxMemory() / 1024).toInt()
    private val cacheSize = maxMemory / 8

    private val memoryCache: LruCache<String, Bitmap> = object : LruCache<String, Bitmap>(cacheSize) {
        override fun sizeOf(key: String, bitmap: Bitmap): Int {
            // Kích thước tính theo Kilobytes
            return bitmap.byteCount / 1024
        }
    }

    fun get(key: String): Bitmap? = memoryCache.get(key)
    fun put(key: String, bitmap: Bitmap) { memoryCache.put(key, bitmap) }
}

import okhttp3.CertificatePinner
import okhttp3.OkHttpClient

fun createSecureHttpClient(): OkHttpClient {
    // Khởi tạo CertificatePinner với mã băm SHA-256 của Public Key
    val certificatePinner = CertificatePinner.Builder()
        // Ghim chứng chỉ chính của server
        .add("api.enterprise.bank.com", "sha256/AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=")
        // BẮT BUỘC: Ghim thêm chứng chỉ dự phòng (Backup Pin) để tránh thảm họa hết hạn SSL
        .add("api.enterprise.bank.com", "sha256/BBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB=")
        .build()

    return OkHttpClient.Builder()
        .certificatePinner(certificatePinner)
        .build()
}

import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.*
import kotlinx.coroutines.CoroutineScope

// 1. COLD FLOW: Chỉ chạy khi có collector, mỗi collector chạy độc lập
fun createColdTicker(): Flow<Int> = flow {
    println("Cold producer bắt đầu chạy...")
    var tick = 0
    while (true) {
        emit(tick++)
        delay(1000)
    }
}

// 2. HOT FLOW: Chuyển đổi Cold sang Hot để chia sẻ cho toàn bộ ứng dụng
class MarketTickerRepository(scope: CoroutineScope) {
    val hotPriceStream: SharedFlow<Int> = createColdTicker()
        .shareIn(
            scope = scope,
            // Chỉ giữ kết nối khi có ít nhất một subscriber UI trên màn hình
            started = SharingStarted.WhileSubscribed(stopTimeoutMillis = 5000),
            replay = 1 // Giữ lại 1 giá trị gần nhất cho collector mới
        )
}

import android.content.Context
import android.content.Intent

// 1. Sử dụng inline và reified để vượt qua giới hạn Type Erasure của Java
inline fun <reified T : Any> Context.launchActivity(block: Intent.() -> Unit = {}) {
    // T::class.java hoạt động được là nhờ reified
    val intent = Intent(this, T::class.java).apply(block)
    startActivity(intent)
}

// 2. Minh họa kết hợp inline và noinline
inline fun executeActions(
    inlinedAction: () -> Unit,
    noinline storedAction: () -> Unit // Không inline để có thể lưu trữ hoặc truyền đi
) {
    inlinedAction() // Code được chép đè thẳng vào call-site
    scheduleForLater(storedAction) // Truyền tham chiếu đối tượng bình thường
}

